using DayZ;
using System;
using System.Collections.Generic;
using UnityEngine;

namespace DayZ
{
    /// <summary>
    /// 矿车管理类
    /// </summary>
    public class MiningManager : IMiningManager, IManager
    {
        public Dictionary<int, List<Vector2>> miningPointDict = new Dictionary<int, List<Vector2>>();
        private bool isDirty = false;
        /// <summary>
        /// 上一次请求矿车信息的服务器ID
        /// </summary>
        private int LastServerId = -1;

        public void Init()
        {
            InitMiningDict();
        }

        public void OnTick(float t)
        {
            if (isDirty)
            {
                isDirty = false;
                UpdateMiningData();
            }
        }

        private void UpdateMiningData()
        {
            Scheduler.Instance.unschedule("UpdataWorldMiningMarchInfo", this);
            Scheduler.Instance.schedule(UpdataWorldMiningMarch, this, 0, 0, 5f, false, "UpdataWorldMiningMarchInfo");
        }

        private void UpdataWorldMiningMarch(float t)
        {
            GetMiningPathByServer(GlobalData.shared().playerInfo.PlayerViewServerId, null);
        }

        public void PraseMiningData(CCDictionary param)
        {
            CCArray arr = (CCArray)param.objectForKey("carts");
            var count = arr.count();
            int inEndStateCount = 0;
            for (int i = 0; i < count; i++)
            {
                var dict = arr.objectAtIndex(i) as CCDictionary;
                if (dict.ContainsKey("status") && dict.IntValueForKey("status") == 0)
                {
                    inEndStateCount++;
                    continue;
                }
                var info = new MarchInfo_Mining(dict);
                if (info.HasEndMarchLine)
                {
                    LogCommon.Log($"矿车: {info.Uuid}; 无效数据 cur: {Global.gGameTime.getWorldMsTime()}");
                    inEndStateCount++;
                    continue;
                }
                if (!WorldController.getInstance().m_marchInfo_mining.ContainsKey(info.Uuid))
                {
                    info.MarchTag = WorldController.getInstance().getMarchTag(MarchMethodType.MINING_MARCH);
                    info.marchLineSkinId = info.quality;
                }
                else
                {
                    info.MarchTag = WorldController.getInstance().m_marchInfo_mining[info.Uuid].MarchTag;
                }
                if (!info.HasEndMarchLine)
                {
                    WorldController.getInstance().m_marchInfo_mining[info.Uuid] = info;
                }
            }
            LogCommon.Log($"矿车数据: {count}；无效数据: {inEndStateCount}；");
        }

        public void Reset()
        {
            isDirty = false;
            Scheduler.Instance.unschedule("UpdataWorldMiningMarchInfo", this);
        }

        public void InitMiningDict()
        {
            if (miningPointDict.Count > 0) return;
            var dict = DataAtlasManager.Instance.GetDataWithType<MiningRoute>();
            if (dict == null) return;
            foreach (MiningRoute item in dict.Values)
            {
                var list = new List<Vector2>();
                foreach (string item2 in item.route)
                {
                    list.Add(new Vector2(int.Parse(item2.Split(',')[0]), int.Parse(item2.Split(',')[1])));
                }
                miningPointDict.Add(int.Parse(item.id), list);
            }
        }

        public List<Vector2> GetMiningPath(int pathId)
        {
            if (miningPointDict.ContainsKey(pathId) == false)
                return null;
            return miningPointDict[pathId];
        }

        public void SetDirty(bool immediately)
        {
            if (immediately)
            {
                isDirty = false;
                UpdataWorldMiningMarch(0);
            }
            else
                isDirty = true;
        }

        public void GetMiningPathByServer(int ServerId, Action callBack)
        {
            if (!CCCommonUtils.IsRedAlert())
                return;
            if (AGameConst.EscortCartList_usePush)
            {
                if (ServerId == LastServerId)
                {
                    return;
                }
                else
                {
                    LastServerId = ServerId;
                }
            }
            WorldMiningsCommand cmd = new WorldMiningsCommand(ServerId, true, false);
            // cmd.GetType().GetProperty("CmdCheckType").SetValue(cmd, CheckType.CHECK_CMD);
            cmd.setSuccessCallback((result) =>
            {
                if (callBack != null)
                    callBack();
            });
            cmd.sendAndRelease();
        }

        public void JumpToMiningPath(string marchId)
        {
            var marchInfos = WorldController.getInstance().m_marchInfo_mining;
            bool exist = marchInfos.ContainsKey(marchId);
            if (exist)
            {
                var marchInfo = marchInfos[marchId];
                if (!marchInfo.checkOverTimeMarch())
                {
                    PopupViewController.getInstance().removeAllPopupView();
                    Container.Instance.Get<ICrossServerManager>().GoToServerPoint(marchInfo.GetCurrentPos(), marchInfo.ServerId);
                    WorldMapView2.instance().getUI()?.showMiningTroopInfo(marchId);
                }
                else
                {
                    LogCommon.LogError($"跳转大地图矿车 marchId：{marchId} ,已失效！");
                }
            }
            else
            {
                LogCommon.LogError($"跳转大地图矿车 marchId：{marchId} ,不存在!");
            }
        }

        public Vector2 GetMiningPathPoint(string marchId)
        {
            if (WorldController.getInstance().m_marchInfo_mining[marchId] != null)
                return Vector2.one;
            return Vector2.one;
        }
    }
}
